<?php $base=$portal?'/portal/tickets':'/tickets'; ?>
<header class="page-header"><div><div class="eyebrow">Support</div><h1><?= $portal?'My Support Tickets':'Support Tickets' ?></h1><p><?= $portal?'Ask for help and follow replies from the Veelox Digital team.':'Manage customer requests, assignments and response workflows.' ?></p></div><a class="primary-button" href="<?= $base ?>/create">+ Open ticket</a></header><?php if($flash): ?><div class="alert <?= htmlspecialchars($flash['type']) ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?>
<section class="list-panel"><form class="toolbar ticket-toolbar" method="get" action="<?= $base ?>"><div class="search-box"><span>⌕</span><input name="search" value="<?= htmlspecialchars($search) ?>" placeholder="Search number, subject or customer..."></div><select name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['open','customer_reply','staff_reply','resolved','closed'] as $value): ?><option value="<?= $value ?>" <?= $status===$value?'selected':'' ?>><?= htmlspecialchars(ucwords(str_replace('_',' ',$value))) ?></option><?php endforeach; ?></select><button class="secondary-button">Search</button></form><?php if(!$tickets): ?><div class="empty-state tall"><span>✦</span><h3>No support tickets</h3><p>There are no tickets matching these filters.</p></div><?php else: ?><div class="ticket-list"><?php foreach($tickets as $ticket): $customer=$ticket['company_name']?:$ticket['contact_name']; ?><a href="<?= $base.'/'.(int)$ticket['id'] ?>"><span class="priority-dot <?= htmlspecialchars((string)$ticket['priority']) ?>"></span><span class="ticket-main"><strong><?= htmlspecialchars((string)$ticket['subject']) ?></strong><small><?= htmlspecialchars((string)$ticket['ticket_number']) ?><?= $portal?'':' · '.htmlspecialchars((string)$customer) ?> · <?= htmlspecialchars((string)$ticket['department_name']) ?></small></span><span class="ticket-replies"><strong><?= (int)$ticket['reply_count'] ?></strong><small>replies</small></span><span class="status <?= htmlspecialchars((string)$ticket['status']) ?>"><?= htmlspecialchars(ucwords(str_replace('_',' ',(string)$ticket['status']))) ?></span><b>›</b></a><?php endforeach; ?></div><?php endif; ?></section>
